"""
Screen 3 — GPU passthrough (optional).
Shows detected discrete GPUs with an opt-in radio toggle.
"""

import gi
gi.require_version("Gtk", "4.0")
gi.require_version("Adw", "1")

from gi.repository import Gtk, Adw

from .base import BasePage
from ..state import WizardState, GPUDevice
from typing import Callable


class GPUScreen(BasePage):
    def __init__(self, state: WizardState, go_to: Callable):
        super().__init__(state, go_to, title="GPU Passthrough", tag="gpu")

    def _build(self):
        self._body.append(
            self.make_page_header(
                "GPU passthrough",
                "Optionally dedicate a discrete GPU to a gaming VM. "
                "This is entirely optional — privacy-focused users can skip this.",
            )
        )

        gpu_wrapper = Adw.PreferencesGroup()
        gpu_wrapper.set_title("Detected discrete GPUs")
        self._body.append(gpu_wrapper)

        # Gtk.ListBox for reliable row management
        self._gpu_list = Gtk.ListBox()
        self._gpu_list.set_selection_mode(Gtk.SelectionMode.NONE)
        self._gpu_list.add_css_class("boxed-list")
        gpu_wrapper.add(self._gpu_list)
        self._gpu_rows: list[Gtk.ListBoxRow] = []

        self._no_gpu_label = Gtk.Label(label="No discrete GPUs detected.")
        self._no_gpu_label.add_css_class("dim-label")
        self._no_gpu_label.set_visible(False)
        self._body.append(self._no_gpu_label)

        # Options — revealed when a GPU is selected
        self._options_group = Adw.PreferencesGroup()
        self._options_group.set_title("Host-side options")
        self._options_group.set_visible(False)
        self._body.append(self._options_group)

        self._lg_row = Adw.SwitchRow()
        self._lg_row.set_title("Install Looking Glass")
        self._lg_row.set_subtitle(
            "Low-latency capture from the gaming VM. "
            "The Looking Glass client is installed via COPR, while the host application (for Windows) can be downloaded from looking-glass.io/downloads. "
        )
        self._lg_row.set_active(True)
        self._lg_row.connect("notify::active", self._on_lg_toggled)
        self._options_group.add(self._lg_row)

        self._contam_banner = Adw.Banner()
        self._contam_banner.set_title(
            "This GPU shares an IOMMU group with other devices. "
            "Passthrough requires an ACS override kernel patch which may reduce "
            "security guarantees. Proceed only if you understand the trade-off."
        )
        self._contam_banner.set_revealed(False)
        self._body.append(self._contam_banner)

        self._btn_row = self.make_button_row(
            back_label="Back",
            back_cb=lambda: self.go_to("back"),
            next_label="Continue",
            next_cb=lambda: self.go_to("appvms"),
        )
        self._body.append(self._btn_row)

        self._first_radio: Gtk.CheckButton | None = None

    def on_enter(self):
        # Remove previously added rows cleanly
        for row in self._gpu_rows:
            self._gpu_list.remove(row)
        self._gpu_rows.clear()
        self._first_radio = None

        gpus = self.state.gpus
        if not gpus:
            self._no_gpu_label.set_visible(True)
            self._gpu_list.set_visible(False)
            return

        for gpu in gpus:
            row = self._make_gpu_row(gpu, self._first_radio)
            self._gpu_list.append(row)
            self._gpu_rows.append(row)
            if self._first_radio is None:
                # Extract the radio button from the row for grouping
                inner = row.get_child()
                self._first_radio = inner.get_first_child()  # the CheckButton

    def _make_gpu_row(self, gpu: GPUDevice, group_leader: "Gtk.CheckButton | None") -> Gtk.ListBoxRow:
        row = Gtk.ListBoxRow()
        row.set_activatable(False)
        row.set_selectable(False)

        inner = Gtk.Box(orientation=Gtk.Orientation.HORIZONTAL, spacing=12)
        inner.set_margin_top(10)
        inner.set_margin_bottom(10)
        inner.set_margin_start(12)
        inner.set_margin_end(12)

        radio = Gtk.CheckButton()
        if group_leader:
            radio.set_group(group_leader)
        radio.set_valign(Gtk.Align.CENTER)
        radio.connect("toggled", self._on_gpu_toggled, gpu)
        inner.append(radio)

        text = Gtk.Box(orientation=Gtk.Orientation.VERTICAL, spacing=2)
        text.set_hexpand(True)

        title_lbl = Gtk.Label(label=gpu.description)
        title_lbl.set_xalign(0)
        title_lbl.set_wrap(True)
        title_lbl.add_css_class("heading")
        text.append(title_lbl)

        group_label = "Isolated IOMMU group" if gpu.group_isolated else "Shared IOMMU group — see warning below"
        sub_lbl = Gtk.Label(
            label=f"IOMMU group {gpu.iommu_group}  ·  {gpu.pci_address}  ·  {group_label}"
        )
        sub_lbl.set_xalign(0)
        sub_lbl.set_wrap(True)
        sub_lbl.add_css_class("caption")
        sub_lbl.add_css_class("dim-label")
        text.append(sub_lbl)

        inner.append(text)

        gesture = Gtk.GestureClick()
        gesture.connect("released", lambda g, n, x, y, r=radio: r.set_active(True))
        row.add_controller(gesture)

        row.set_child(inner)
        return row

    def _on_gpu_toggled(self, radio: Gtk.CheckButton, gpu: GPUDevice):
        if radio.get_active():
            self.state.gpu_passthrough = True
            self.state.selected_gpu = gpu
            self._options_group.set_visible(True)
            self._contam_banner.set_revealed(not gpu.group_isolated)
            self.state.install_looking_glass = self._lg_row.get_active()
        else:
            if self.state.selected_gpu is gpu:
                self.state.gpu_passthrough = False
                self.state.selected_gpu = None
                self._options_group.set_visible(False)
                self._contam_banner.set_revealed(False)

    def _on_lg_toggled(self, row, _param):
        self.state.install_looking_glass = row.get_active()
